using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments = new()
    {
        new Department { Id = 1, Name = "Computer Science", Abbreviation = "CS" },
        new Department { Id = 2, Name = "Mathematics", Abbreviation = "MATH" },
        new Department { Id = 3, Name = "Physics", Abbreviation = "PHYS" },
        new Department { Id = 4, Name = "English", Abbreviation = "ENG" },
        new Department { Id = 5, Name = "History", Abbreviation = "HIST" }
    };

    private readonly List<Course> _courses = new()
    {
        new Course
        {
            Id = 1, CourseCode = "CS 101", Title = "Introduction to Programming",
            Description = "An introductory course covering fundamental programming concepts using Python. Topics include variables, control flow, functions, data structures, and basic object-oriented programming.",
            Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentId = 1, IsFeatured = true,
            InstructorName = "Dr. Sarah Chen",
            InstructorBio = "Dr. Chen holds a Ph.D. in Computer Science from MIT and has 12 years of teaching experience. Her research focuses on programming language design and CS education."
        },
        new Course
        {
            Id = 2, CourseCode = "CS 301", Title = "Data Structures and Algorithms",
            Description = "Study of fundamental data structures (trees, graphs, hash tables) and algorithm design techniques (divide and conquer, dynamic programming, greedy algorithms). Includes complexity analysis.",
            Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", DepartmentId = 1, IsFeatured = true,
            InstructorName = "Dr. James Park",
            InstructorBio = "Dr. Park is an ACM Distinguished Educator with over 50 publications in algorithm design. He previously worked at Google Research before joining academia."
        },
        new Course
        {
            Id = 3, CourseCode = "CS 450", Title = "Machine Learning",
            Description = "Introduction to machine learning techniques including supervised learning, unsupervised learning, neural networks, and reinforcement learning. Hands-on projects using real-world datasets.",
            Credits = 4, Schedule = "Mon/Wed 2:00–3:20 PM", DepartmentId = 1, IsFeatured = false,
            InstructorName = "Dr. Maria Rodriguez",
            InstructorBio = "Dr. Rodriguez specializes in deep learning and natural language processing. She spent 5 years at a leading AI research lab before joining the faculty."
        },
        new Course
        {
            Id = 4, CourseCode = "MATH 201", Title = "Linear Algebra",
            Description = "Vectors, matrices, linear transformations, eigenvalues, and applications. Essential for students pursuing computer science, physics, or engineering.",
            Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", DepartmentId = 2, IsFeatured = true,
            InstructorName = "Dr. Robert Liu",
            InstructorBio = "Dr. Liu is an award-winning mathematics educator who has authored three textbooks on linear algebra and its applications in data science."
        },
        new Course
        {
            Id = 5, CourseCode = "MATH 310", Title = "Probability and Statistics",
            Description = "Probability theory, random variables, distributions, hypothesis testing, regression analysis, and Bayesian inference with applications in science and engineering.",
            Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", DepartmentId = 2, IsFeatured = false,
            InstructorName = "Dr. Emily Watson",
            InstructorBio = "Dr. Watson is a statistician with expertise in biostatistics. She has consulted for several pharmaceutical companies on clinical trial design."
        },
        new Course
        {
            Id = 6, CourseCode = "PHYS 101", Title = "General Physics I",
            Description = "Mechanics, thermodynamics, and waves. Covers Newton's laws, energy conservation, rotational motion, oscillations, and introduction to thermodynamic principles.",
            Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM + Lab Thu 2:00–4:50 PM", DepartmentId = 3, IsFeatured = true,
            InstructorName = "Dr. Alan Foster",
            InstructorBio = "Dr. Foster is a physicist with 20 years of teaching experience. He is passionate about making physics accessible through hands-on experiments and demonstrations."
        },
        new Course
        {
            Id = 7, CourseCode = "PHYS 320", Title = "Quantum Mechanics",
            Description = "Introduction to quantum theory: wave-particle duality, Schrödinger equation, quantum states, measurement, angular momentum, and applications to atomic physics.",
            Credits = 4, Schedule = "Tue/Thu 9:00–10:20 AM", DepartmentId = 3, IsFeatured = false,
            InstructorName = "Dr. Nina Patel",
            InstructorBio = "Dr. Patel is a theoretical physicist whose research focuses on quantum information theory. She has published extensively in Physical Review Letters."
        },
        new Course
        {
            Id = 8, CourseCode = "ENG 110", Title = "College Writing",
            Description = "Develop effective writing skills through essay composition, peer review, and revision. Focus on argumentation, research writing, and clear academic prose.",
            Credits = 3, Schedule = "Mon/Wed 10:00–11:20 AM", DepartmentId = 4, IsFeatured = false,
            InstructorName = "Prof. David Okafor",
            InstructorBio = "Prof. Okafor is a published novelist and writing instructor who has taught composition at three universities. He emphasizes the connection between reading and writing craft."
        },
        new Course
        {
            Id = 9, CourseCode = "ENG 350", Title = "American Literature",
            Description = "A survey of American literary traditions from the colonial era to the present, including works by Hawthorne, Twain, Fitzgerald, Morrison, and contemporary voices.",
            Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", DepartmentId = 4, IsFeatured = false,
            InstructorName = "Dr. Catherine Brooks",
            InstructorBio = "Dr. Brooks specializes in 20th-century American fiction. She is the author of two scholarly monographs and regularly presents at MLA conferences."
        },
        new Course
        {
            Id = 10, CourseCode = "HIST 101", Title = "World History to 1500",
            Description = "Survey of world civilizations from prehistory through the early modern period. Examines political, economic, social, and cultural developments across major world regions.",
            Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", DepartmentId = 5, IsFeatured = false,
            InstructorName = "Dr. Thomas Grant",
            InstructorBio = "Dr. Grant is a historian specializing in ancient Mediterranean civilizations. He has led archaeological expeditions in Greece and Turkey."
        },
        new Course
        {
            Id = 11, CourseCode = "HIST 275", Title = "Modern European History",
            Description = "Europe from the French Revolution to the present day. Covers industrialization, nationalism, world wars, the Cold War, and European integration.",
            Credits = 3, Schedule = "Tue/Thu 3:00–4:20 PM", DepartmentId = 5, IsFeatured = true,
            InstructorName = "Dr. Anna Bergmann",
            InstructorBio = "Dr. Bergmann is a specialist in modern German history. She earned her doctorate from the University of Oxford and has authored a critically acclaimed book on post-war Europe."
        }
    };

    public IReadOnlyList<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public IReadOnlyList<Course> GetAllCourses() => _courses;

    public IReadOnlyList<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public IReadOnlyList<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public IReadOnlyList<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();
}

